-- package: prop4you/leadfinder_group
-- file: 0005_canonical_jsonschema_registry.sql
-- status: experimental / non-final
-- purpose: Queryable registry for LFG canonical JSONSchema envelopes and JSONB-to-relational projection policy.
-- depends-on: leadfinder_group/0004_user_feedback_markers.sql
-- idempotency: idempotent
-- destructive: false
-- [GATEWAY_AGNOSTIC]
-- [REGISTRY_ONLY]
-- [NO_PROVIDER_CALLS]
-- [NO_RAW_PAYLOAD_VALUES]
-- [NO_FINAL_PRODUCT_TABLE_EXPLOSION]

set search_path = prop4you_leadfinder_group, public;

create table if not exists prop4you_leadfinder_group.projection_policies (
  id uuid primary key default uuidv7(),
  public_ref text generated always as (base.make_public_ref('p4ylfgpp', id)) stored,
  policy_key text not null,
  policy_status text not null default 'active',
  policy_version text not null default 'v1',
  policy_title text not null,
  policy_path text not null,
  policy_sha256 text,
  policy_doc jsonb not null,
  raw_value_policy text not null default 'no_raw_payload_values',
  notes text,
  metadata jsonb not null default '{}'::jsonb,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1,
  constraint projection_policies_public_ref_key unique (public_ref),
  constraint projection_policies_key_version_key unique (policy_key, policy_version),
  constraint projection_policies_key_format_chk check (policy_key ~ '^[a-z][a-z0-9_.:-]{1,191}$'),
  constraint projection_policies_status_chk check (policy_status in ('draft','active','deprecated','superseded','archived')),
  constraint projection_policies_version_format_chk check (policy_version ~ '^v[0-9]+([.][0-9]+)?$'),
  constraint projection_policies_doc_object_chk check (jsonb_typeof(policy_doc) = 'object'),
  constraint projection_policies_required_gates_chk check (jsonb_array_length(policy_doc->'promotion_gates') >= 7),
  constraint projection_policies_sha_chk check (policy_sha256 is null or policy_sha256 ~ '^[0-9a-f]{64}$'),
  constraint projection_policies_raw_policy_chk check (raw_value_policy in ('no_raw_payload_values','hashes_and_refs_only','normalized_values_allowed_internal','unknown')),
  constraint projection_policies_metadata_chk check (jsonb_typeof(metadata) = 'object'),
  constraint projection_policies_version_positive_chk check (version > 0)
);

comment on table prop4you_leadfinder_group.projection_policies is
'LFG registry of JSONB-to-relational projection policies. Governance metadata only: no provider calls, no raw payload values, no final product table explosion.';

create table if not exists prop4you_leadfinder_group.canonical_jsonschema_envelopes (
  id uuid primary key default uuidv7(),
  public_ref text generated always as (base.make_public_ref('p4ylfgjs', id)) stored,
  envelope_key text not null,
  envelope_status text not null default 'active',
  envelope_kind text not null,
  schema_version text not null default 'v1',
  schema_id text not null,
  schema_title text not null,
  schema_path text not null,
  schema_sha256 text,
  json_schema jsonb not null,
  projection_policy_key text,
  pii_classification text not null default 'mixed_review_required',
  raw_value_policy text not null default 'no_raw_payload_values',
  notes text,
  metadata jsonb not null default '{}'::jsonb,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1,
  constraint canonical_jsonschema_envelopes_public_ref_key unique (public_ref),
  constraint canonical_jsonschema_envelopes_key_version_key unique (envelope_key, schema_version),
  constraint canonical_jsonschema_envelopes_schema_id_key unique (schema_id),
  constraint canonical_jsonschema_envelopes_key_format_chk check (envelope_key ~ '^[a-z][a-z0-9_.:-]{1,191}$'),
  constraint canonical_jsonschema_envelopes_version_format_chk check (schema_version ~ '^v[0-9]+([.][0-9]+)?$'),
  constraint canonical_jsonschema_envelopes_status_chk check (envelope_status in ('draft','active','deprecated','superseded','archived')),
  constraint canonical_jsonschema_envelopes_kind_chk check (envelope_kind in ('property','owner','contact_satellites','realtor_evidence','taxonomy','canonical_index','unknown')),
  constraint canonical_jsonschema_envelopes_schema_object_chk check (jsonb_typeof(json_schema)='object'),
  constraint canonical_jsonschema_envelopes_schema_required_keys_chk check (json_schema ? '$schema' and json_schema ? '$id' and json_schema ? 'title' and json_schema ? 'type'),
  constraint canonical_jsonschema_envelopes_schema_type_object_chk check (json_schema->>'type' = 'object'),
  constraint canonical_jsonschema_envelopes_additional_props_present_chk check (json_schema ? 'additionalProperties'),
  constraint canonical_jsonschema_envelopes_sha_chk check (schema_sha256 is null or schema_sha256 ~ '^[0-9a-f]{64}$'),
  constraint canonical_jsonschema_envelopes_pii_chk check (pii_classification in ('none','public','internal','pii','mixed_review_required','unknown')),
  constraint canonical_jsonschema_envelopes_raw_policy_chk check (raw_value_policy in ('no_raw_payload_values','hashes_and_refs_only','normalized_values_allowed_internal','unknown')),
  constraint canonical_jsonschema_envelopes_metadata_chk check (jsonb_typeof(metadata)='object'),
  constraint canonical_jsonschema_envelopes_version_positive_chk check (version > 0),
  constraint canonical_jsonschema_envelopes_policy_fk foreign key (projection_policy_key, schema_version)
    references prop4you_leadfinder_group.projection_policies(policy_key, policy_version)
    deferrable initially deferred
);

comment on table prop4you_leadfinder_group.canonical_jsonschema_envelopes is
'Queryable registry for LFG canonical JSONSchema envelopes. JSONB-first governance artifact; does not create final property/owner/contact/workspace product tables.';

create index if not exists projection_policies_status_idx on prop4you_leadfinder_group.projection_policies (policy_status, policy_version, created_at desc) where active = true;
create index if not exists projection_policies_doc_gin_idx on prop4you_leadfinder_group.projection_policies using gin (policy_doc jsonb_path_ops);
create index if not exists canonical_jsonschema_envelopes_status_idx on prop4you_leadfinder_group.canonical_jsonschema_envelopes (envelope_status, envelope_kind, created_at desc) where active = true;
create index if not exists canonical_jsonschema_envelopes_schema_gin_idx on prop4you_leadfinder_group.canonical_jsonschema_envelopes using gin (json_schema jsonb_path_ops);

insert into prop4you_leadfinder_group.projection_policies (policy_key, policy_status, policy_version, policy_title, policy_path, policy_sha256, policy_doc, raw_value_policy, notes, metadata, active)
values ('lfg_projection_policy.v1', 'active', 'v1', 'Prop4You LFG JSONB-to-relational projection policy v1', 'docs/schemas/prop4you/lfg/projection-policy.v1.json', '061bac7bc3a2c682af9f7fd1e9da9a2b0e14bbd239305e932c5a4b25a8c824f6', $POLICY${"jsonb_default": ["raw_payload", "provider_residue", "variable_arrays", "matrix_artifacts", "review_payloads", "canonical_envelopes_before_projection"], "low_risk_marker_auto_apply_default": {"audit_event_required": true, "marker_risk_class": "low", "min_distinct_users": 3, "min_distinct_workspaces": 2, "no_active_disputes": true}, "non_goals": ["no_final_graph_table_explosion", "no_workspace_tables", "no_provider_calls", "no_raw_values_in_docs", "no_public_api_rls_until_envelopes_stabilize"], "policy_key": "lfg_projection_policy.v1", "policy_version": "v1", "promotion_gates": [{"gate_key": "representative_corpus_observed", "gate_number": 1, "required": true}, {"gate_key": "matrix_leadfinder_semantic_approval", "gate_number": 2, "required": true}, {"gate_key": "stable_or_intentionally_provider_specific", "gate_number": 3, "required": true}, {"gate_key": "query_join_filter_sort_unique_fk_rls_postgis_or_constraint_need", "gate_number": 4, "required": true}, {"gate_key": "safe_cast_or_coercion_exists", "gate_number": 5, "required": true}, {"gate_key": "durable_lineage_to_raw_json", "gate_number": 6, "required": true}, {"gate_key": "privacy_pii_classified", "gate_number": 7, "required": true}], "relational_default": ["identity_anchors", "graph_edges", "constraints", "auth_boundaries", "postgis_geometry", "temporal_snapshots", "high_value_indexed_projections"], "rule_summary": "JSONB-first for evidence/envelopes; relational-first for anchors, edges, constraints, PostGIS, temporal snapshots, and high-value indexed projections.", "title": "Prop4You LFG JSONB-to-relational projection policy v1"}$POLICY$::jsonb, 'no_raw_payload_values', 'Seeded from repo projection policy artifact. Default rule: JSONB-first until all promotion gates pass.', '{}'::jsonb, true)
on conflict (policy_key, policy_version) do update set policy_status=excluded.policy_status, policy_title=excluded.policy_title, policy_path=excluded.policy_path, policy_sha256=excluded.policy_sha256, policy_doc=excluded.policy_doc, raw_value_policy=excluded.raw_value_policy, notes=excluded.notes, active=excluded.active, updated_at=now(), version=prop4you_leadfinder_group.projection_policies.version+1;

