create or replace view prop4you_leadfinder_group.v_active_canonical_jsonschema_envelopes as
select envelope_key, envelope_kind, schema_version, schema_id, schema_title, schema_path, schema_sha256, projection_policy_key, pii_classification, raw_value_policy, json_schema->>'additionalProperties' as top_level_additional_properties, created_at, updated_at
from prop4you_leadfinder_group.canonical_jsonschema_envelopes
where active = true and envelope_status = 'active';

comment on view prop4you_leadfinder_group.v_active_canonical_jsonschema_envelopes is
'Active LFG canonical JSONSchema envelope registry view for runtime/review introspection. Registry-only; no raw payload values.';

create or replace view prop4you_leadfinder_group.v_active_projection_policy_gates as
select p.policy_key, p.policy_version, gate.value->>'gate_key' as gate_key, (gate.value->>'gate_number')::integer as gate_number, coalesce((gate.value->>'required')::boolean, false) as required
from prop4you_leadfinder_group.projection_policies p
cross join lateral jsonb_array_elements(p.policy_doc->'promotion_gates') as gate(value)
where p.active = true and p.policy_status = 'active';

comment on view prop4you_leadfinder_group.v_active_projection_policy_gates is
'Queryable seven-gate policy for deciding whether a JSONB path may become a relational projection.';
